// @ts-check
/**
 * E2E coverage for feature 37 (pdf_highlight): capture inside the extension's
 * own PDF viewer (src/viewer.html), persistence + per-page re-anchoring after
 * reload, the side panel's PDF grouping/"Fuente" line, and go-to-source back
 * into the viewer.
 *
 * The PDF is a local fixture (fixtures/sample.pdf, regenerated by
 * fixtures/make-sample-pdf.mjs) served by a throwaway Node HTTP server:
 * page.route() can't reliably intercept requests made by extension pages or
 * the PDF.js worker. Selection uses real mouse drags over PDF.js' text layer,
 * like 029 does on web pages — capture/ui.js only reacts to a native mouseup.
 */
import http from "node:http";
import fs from "node:fs";
import path from "node:path";
import { test, expect } from "./fixtures.js";

const FIXTURE_PDF = path.resolve(process.cwd(), "tests/e2e/fixtures/sample.pdf");
const CONTEXT_NAME = "E2E PDF";
const TARGET_TEXT = "La memoria de trabajo tiene capacidad limitada.";

/** @type {http.Server} */
let server;
let baseUrl = "";
let pdfUrl = "";

test.beforeAll(async () => {
  server = http.createServer((req, res) => {
    if ((req.url || "").startsWith("/sample.pdf")) {
      res.writeHead(200, { "Content-Type": "application/pdf" });
      fs.createReadStream(FIXTURE_PDF).pipe(res);
    } else {
      res.writeHead(404, { "Content-Type": "text/plain" });
      res.end("not found");
    }
  });
  await new Promise((resolve) => server.listen(0, "127.0.0.1", () => resolve(undefined)));
  const address = server.address();
  const port = typeof address === "object" && address ? address.port : 0;
  baseUrl = `http://127.0.0.1:${port}`;
  pdfUrl = `${baseUrl}/sample.pdf`;
});

test.afterAll(async () => {
  await new Promise((resolve) => server.close(() => resolve(undefined)));
});

function viewerUrl(extensionId, file, hash = "") {
  return `chrome-extension://${extensionId}/src/viewer.html?file=${encodeURIComponent(file)}${hash}`;
}

/** Leaf text-layer span of `pageNumber` containing `text`. */
function textSpan(page, pageNumber, text) {
  return page
    .locator(`.page[data-page-number="${pageNumber}"] .textLayer span:not(:has(span))`, { hasText: text })
    .first();
}

async function getWorker(context) {
  let [worker] = context.serviceWorkers();
  if (!worker) worker = await context.waitForEvent("serviceworker");
  return worker;
}

/** Saved items whose sourceUrl is `url`. */
async function savedItemsFor(context, url) {
  const worker = await getWorker(context);
  return worker.evaluate(async (targetUrl) => {
    const { contextHighlighter } = await chrome.storage.local.get("contextHighlighter");
    const out = [];
    for (const ctx of Object.values(contextHighlighter?.contexts ?? {})) {
      for (const item of ctx.items ?? []) if (item.sourceUrl === targetUrl) out.push(item);
    }
    return out;
  }, url);
}

/** Text of every range painted under `ch-hl-{category}` in `page`. */
function paintedTexts(page, category = "idea") {
  return page.evaluate(
    (name) => [...(CSS.highlights.get(name) ?? [])].map((r) => r.toString()),
    `ch-hl-${category}`
  );
}

/**
 * Bounding box once layout has settled. PDF.js applies the 'auto' zoom right
 * after the first text layer appears, so an immediate read can measure the
 * span at its pre-zoom size and the drag would select only a few letters.
 */
async function stableBox(page, locator) {
  let prev = null;
  for (let i = 0; i < 40; i++) {
    const box = await locator.boundingBox();
    if (box && prev && JSON.stringify(box) === JSON.stringify(prev)) return box;
    prev = box;
    await page.waitForTimeout(100);
  }
  throw new Error("text span never settled");
}

/** Real mouse drag from the left edge of `from` to the right edge of `to`. */
async function dragSelect(page, from, to) {
  const a = await stableBox(page, from);
  const b = await stableBox(page, to);
  await page.mouse.move(a.x + 1, a.y + a.height / 2);
  await page.mouse.down();
  await page.mouse.move(b.x + b.width - 1, b.y + b.height / 2, { steps: 10 });
  await page.mouse.up();
}

/** Open the viewer on page 2, select TARGET_TEXT and save it under CONTEXT_NAME. */
async function captureOnPage2(page, extensionId) {
  await page.goto(viewerUrl(extensionId, pdfUrl, "#page=2"));
  const span = textSpan(page, 2, "La memoria de trabajo");
  await expect(span).toBeVisible({ timeout: 15000 });
  await dragSelect(page, span, span);

  const toolbar = page.locator(".ch-toolbar");
  await expect(toolbar).toBeVisible();
  await toolbar.locator(".ch-toolbar-more").click({ force: true });

  const popup = page.locator(".ch-pop");
  await expect(popup).toBeVisible();
  await popup.locator(".ch-combo-input").fill(CONTEXT_NAME);
  await popup.locator('[data-role="save"]').click();
  await expect(popup).toBeHidden();
}

test.describe("feature 37 — resaltar PDFs en el visor propio", () => {
  test("captura en la página 2, guarda page/sourceTitle y re-pinta tras recargar", async ({
    page,
    context,
    extensionId,
  }) => {
    test.setTimeout(60000);
    const pageErrors = [];
    page.on("pageerror", (err) => pageErrors.push(err.message));

    await captureOnPage2(page, extensionId);

    const [item] = await savedItemsFor(context, pdfUrl);
    expect(item).toBeTruthy();
    expect(item.page).toBe(2);
    expect(item.sourceTitle).toBe("sample.pdf");
    expect(item.source).toBe("sample.pdf");
    expect(item.rangePrefix).not.toBeNull();
    expect(item.text).toContain("memoria de trabajo");

    // Painted live right after saving…
    await expect.poll(() => paintedTexts(page)).toEqual([expect.stringContaining("memoria de trabajo")]);

    // …and re-anchored from storage after a reload, once page 2's text layer renders.
    await page.reload();
    await expect(textSpan(page, 2, "La memoria de trabajo")).toBeVisible({ timeout: 15000 });
    await expect
      .poll(() => paintedTexts(page), { timeout: 10000 })
      .toEqual([expect.stringContaining("memoria de trabajo")]);

    expect(pageErrors).toEqual([]);
  });

  test("la Vista agrupa por nombre de archivo, muestra 'Fuente: sample.pdf, p. 2' e ir al origen vuelve al visor", async ({
    page,
    context,
    extensionId,
  }) => {
    test.setTimeout(60000);
    await captureOnPage2(page, extensionId);
    const [item] = await savedItemsFor(context, pdfUrl);
    const viewerTabId = await page.evaluate(async () => (await chrome.tabs.getCurrent())?.id);

    const panel = await context.newPage();
    await panel.goto(`chrome-extension://${extensionId}/src/sidebar.html`);
    const link = panel.locator(".vista-source-link");
    await expect(link).toHaveCount(1);
    await expect(link.locator(".vista-source-label")).toHaveText("sample.pdf");
    await expect(panel.locator(".vista-md-preview")).toContainText("Fuente: sample.pdf, p. 2");

    // Viewer already open → focus it, no duplicate tab.
    await link.click();
    const worker = await getWorker(context);
    await expect
      .poll(() => worker.evaluate(async (id) => (await chrome.tabs.get(id)).active, viewerTabId))
      .toBe(true);

    // Viewer closed → a new viewer tab opens at the item's page and paints it.
    await page.close();
    await panel.bringToFront();
    const [opened] = await Promise.all([context.waitForEvent("page"), link.click()]);
    await opened.waitForLoadState("domcontentloaded");
    expect(opened.url()).toContain("/src/viewer.html?file=" + encodeURIComponent(pdfUrl));
    expect(opened.url()).toContain(`#page=2&item=${item.id}`);
    await expect
      .poll(() => paintedTexts(opened), { timeout: 15000 })
      .toEqual([expect.stringContaining("memoria de trabajo")]);

    await panel.close();
  });

  test("una selección que cruza dos páginas no se guarda y muestra el aviso", async ({
    page,
    context,
    extensionId,
  }) => {
    test.setTimeout(60000);
    await page.goto(viewerUrl(extensionId, pdfUrl));
    await expect(textSpan(page, 1, "Final de la pagina uno")).toBeVisible({ timeout: 15000 });

    // Center the page 1 / page 2 boundary so the end of one and the start of
    // the next are both on screen.
    await page.evaluate(() => {
      const container = document.getElementById("viewerContainer");
      const page2 = document.querySelector('.page[data-page-number="2"]');
      container.scrollTop = page2.offsetTop - container.clientHeight / 2;
    });
    const from = textSpan(page, 1, "Final de la pagina uno");
    const to = textSpan(page, 2, "La memoria de trabajo");
    await expect(to).toBeVisible({ timeout: 15000 });
    await dragSelect(page, from, to);

    const hint = page.locator(".ch-toolbar-msg");
    await expect(hint).toBeVisible();
    await expect(hint).toHaveText("Selecciona texto dentro de una sola página");
    await expect(page.locator(".ch-toolbar-swatch")).toHaveCount(0);
    expect(await savedItemsFor(context, pdfUrl)).toEqual([]);
  });

  test("file:// sin permiso muestra el aviso de acceso (con permiso, carga el PDF)", async ({ page, extensionId }) => {
    test.setTimeout(30000);
    await page.goto(viewerUrl(extensionId, `file://${FIXTURE_PDF}`));
    const allowed = await page.evaluate(() => chrome.extension.isAllowedFileSchemeAccess());
    if (allowed) {
      await expect(textSpan(page, 1, "Pagina uno")).toBeVisible({ timeout: 15000 });
    } else {
      await expect(page.locator("#vw-state")).toBeVisible();
      await expect(page.locator("#vw-state-title")).toHaveText("Activa el acceso a archivos locales");
    }
  });

  test("un PDF que no existe muestra un error amable con enlace al visor de Chrome", async ({ page, extensionId }) => {
    test.setTimeout(30000);
    const pageErrors = [];
    page.on("pageerror", (err) => pageErrors.push(err.message));
    const missing = `${baseUrl}/no-existe.pdf`;
    await page.goto(viewerUrl(extensionId, missing));

    await expect(page.locator("#vw-state")).toBeVisible({ timeout: 15000 });
    await expect(page.locator("#vw-state-title")).toHaveText("No se pudo abrir el PDF");
    await expect(page.locator("#vw-state-body")).toContainText("404");
    await expect(page.locator("#vw-state-actions a")).toHaveAttribute("href", missing);
    expect(pageErrors).toEqual([]);
  });
});
